      .home-page {
        overflow-x: hidden;
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        color: #333;
      }

      /* Hero Section */
      .hero-section {
        position: relative;
        background: linear-gradient(rgba(0, 40, 80, 0.8), rgba(0, 40, 80, 0.8)),
                    url('https://images.unsplash.com/photo-1593111774240-d529f12e5c4f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1770&q=80');
        background-size: cover;
        background-position: center;
        min-height: 100vh;
        color: white;
        text-align: center;
        overflow: hidden;
        display: flex;
        align-items: center;
      }

      .hero-overlay {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: radial-gradient(circle, rgba(10, 61, 98, 0.6) 0%, rgba(5, 30, 50, 0.9) 100%);
      }

      .hero-title {
        font-size: 3.5rem;
        font-weight: 800;
        margin-bottom: 20px;
        text-shadow: 0 2px 10px rgba(0,0,0,0.3);
        position: relative;
      }

      .hero-subtitle {
        font-size: 1.8rem;
        margin-bottom: 20px;
        font-weight: 300;
        position: relative;
      }

      .hero-text {
        font-size: 1.2rem;
        max-width: 700px;
        margin: 0 auto 30px;
        opacity: 0.9;
        position: relative;
      }

      /* Mission Section */
      .mission-section {
        background: #f8f9fa;
        padding: 80px 0;
      }

      .section-title {
        font-size: 2.5rem;
        font-weight: 800;
        margin-bottom: 15px;
        color: #0a3d62;
        position: relative;
      }

      .section-title:after {
        content: '';
        position: absolute;
        bottom: -10px;
        left: 50%;
        transform: translateX(-50%);
        width: 80px;
        height: 4px;
        background: linear-gradient(90deg, #1a936f, #88d498);
        border-radius: 2px;
      }

      .section-subtitle {
        font-size: 1.2rem;
        color: #5a7a8c;
        max-width: 600px;
        margin: 0 auto;
      }

      .mission-card {
        padding: 30px 25px;
        border-radius: 15px;
        text-align: center;
        height: 100%;
        background: white;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
        transition: all 0.3s ease;
      }

      .mission-card:hover {
        transform: translateY(-10px);
        box-shadow: 0 15px 40px rgba(0, 100, 200, 0.1);
      }

      .mission-icon {
        width: 80px;
        height: 80px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        margin: 0 auto 20px;
        font-size: 2rem;
        background: linear-gradient(135deg, #0a3d62, #64c8fa);
        color: white;
        box-shadow: 0 5px 15px rgba(10, 61, 98, 0.2);
      }

      .mission-card h3 {
        font-size: 1.5rem;
        color: #0a3d62;
        margin-bottom: 15px;
      }

      .mission-card p {
        color: #5a7a8c;
      }

      /* Tilapia Section */
      .tilapia-section {
        background: linear-gradient(to bottom, #e9f7fe, #d1edfc);
        padding: 80px 0;
      }

      .tilapia-image {
        height: 400px;
        background: url('https://images.unsplash.com/photo-1593111774240-d529f12e5c4f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1770&q=80');
        background-size: cover;
        background-position: center;
        border-radius: 15px;
        box-shadow: 0 15px 30px rgba(0, 50, 100, 0.1);
      }

      .tilapia-content {
        padding: 30px;
        background: white;
        border-radius: 15px;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
      }

      .tilapia-content h3 {
        font-size: 1.8rem;
        color: #0a3d62;
        margin-bottom: 20px;
      }

      .tilapia-content p {
        color: #5a7a8c;
        font-size: 1.1rem;
        margin-bottom: 25px;
      }

      .tilapia-features {
        margin-bottom: 30px;
      }

      .feature {
        display: flex;
        align-items: center;
        margin-bottom: 15px;
