import React from 'react';
import { Container, Row, Col } from 'react-bootstrap';

const Home = () => (
  <div className="home-page">
    {/* Hero Section */}
    <section className="hero-section">
      <div className="hero-overlay"></div>
      <Container>
        <Row className="justify-content-center align-items-center min-vh-80">
          <Col lg={8} className="text-center">
            <h1 className="hero-title">BUKANI MAMA TOTO</h1>
            <p className="hero-subtitle">Empowering Women Through Sustainable Aquaculture</p>
            <p className="hero-text">
              A community-based women's group dedicated to tilapia farming and family nutrition, 
              transforming lives along Lake Victoria with fresh, sustainably harvested fish.
            </p>
          </Col>
        </Row>
      </Container>
    </section>

    {/* Mission Section */}
    <section className="mission-section py-5">
      <Container>
        <Row className="justify-content-center">
          <Col lg={8} className="text-center mb-5">
            <h2 className="section-title">Our Mission</h2>
            <p className="section-subtitle">
              We're dedicated to empowering women through sustainable tilapia farming practices
            </p>
          </Col>
        </Row>
        
        <Row className="g-4">
          <Col md={4} className="d-flex">
            <div className="mission-card">
              <div className="mission-icon">
                <i className="bi bi-people"></i>
              </div>
              <h3>Women Empowerment</h3>
              <p>
                Creating economic opportunities for women through tilapia farming, 
                promoting financial independence and leadership.
              </p>
            </div>
          </Col>
          
          <Col md={4} className="d-flex">
            <div className="mission-card">
              <div className="mission-icon">
                <i className="bi bi-droplet"></i>
              </div>
              <h3>Sustainability</h3>
              <p>
                Environmentally responsible aquaculture practices that protect 
                Lake Victoria's ecosystem for future generations.
              </p>
            </div>
          </Col>
          
          <Col md={4} className="d-flex">
            <div className="mission-card">
              <div className="mission-icon">
                <i className="bi bi-heart"></i>
              </div>
              <h3>Nutrition Security</h3>
              <p>
                Providing high-quality protein sources to improve family nutrition 
                and combat malnutrition in our communities.
              </p>
            </div>
          </Col>
        </Row>
      </Container>
    </section>

    {/* Tilapia Section */}
    <section className="tilapia-section py-5">
      <Container>
        <Row className="justify-content-center mb-5">
          <Col lg={8} className="text-center">
            <h2 className="section-title">Our Fresh Tilapia</h2>
            <p className="section-subtitle">
              Sustainably farmed in Lake Victoria waters
            </p>
          </Col>
        </Row>
        
        <Row className="g-4 align-items-center">
          <Col lg={6}>
            <div className="tilapia-image"></div>
          </Col>
          
          <Col lg={6}>
            <div className="tilapia-content">
              <h3>Premium Quality Tilapia</h3>
              <p>
                We offer only the freshest, raw Nile Tilapia harvested daily from our 
                sustainable cage farming operations in Lake Victoria.
              </p>
              
              <div className="tilapia-features">
                <div className="feature">
                  <i className="bi bi-check-circle"></i>
                  <span>Harvested fresh daily</span>
                </div>
                <div className="feature">
                  <i className="bi bi-check-circle"></i>
                  <span>Never frozen or processed</span>
                </div>
                <div className="feature">
                  <i className="bi bi-check-circle"></i>
                  <span>Sustainably farmed</span>
                </div>
                <div className="feature">
                  <i className="bi bi-check-circle"></i>
                  <span>Chemical-free operations</span>
                </div>
              </div>
              
              <div className="tilapia-pricing">
                <div className="price">KES 400/kg</div>
                <div className="note">Available in whole fish form only</div>
              </div>
            </div>
          </Col>
        </Row>
      </Container>
    </section>

    {/* Impact Section */}
    <section className="impact-section py-5">
      <Container>
        <Row className="justify-content-center mb-5">
          <Col lg={8} className="text-center">
            <h2 className="section-title">Our Community Impact</h2>
            <p className="section-subtitle">
              Transforming lives through sustainable aquaculture
            </p>
          </Col>
        </Row>
        
        <Row className="g-4">
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">250+</div>
              <div className="stat-label">Women Empowered</div>
            </div>
          </Col>
          
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">15</div>
              <div className="stat-label">Farming Groups</div>
            </div>
          </Col>
          
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">50K+</div>
              <div className="stat-label">Tilapia Harvested</div>
            </div>
          </Col>
          
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">100%</div>
              <div className="stat-label">Sustainable Practices</div>
            </div>
          </Col>
        </Row>
      </Container>
    </section>

    <style jsx>{`
      .home-page {
        overflow-x: hidden;
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        color: #333;
      }
      
      /* Hero Section */
      .hero-section {
        position: relative;
        background: linear-gradient(rgba(0, 40, 80, 0.8), rgba(0, 40, 80, 0.8)),
                    url('https://images.unsplash.com/photo-1593111774240-d529f12e5c4f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1770&q=80');
        background-size: cover;
        background-position: center;
        min-height: 100vh;
        color: white;
        text-align: center;
        overflow: hidden;
        display: flex;
        align-items: center;
      }
      
      .hero-overlay {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: radial-gradient(circle, rgba(10, 61, 98, 0.6) 0%, rgba(5, 30, 50, 0.9) 100%);
      }
      
      .hero-title {
        font-size: 3.5rem;
        font-weight: 800;
        margin-bottom: 20px;
        text-shadow: 0 2px 10px rgba(0,0,0,0.3);
        position: relative;
      }
      
      .hero-subtitle {
        font-size: 1.8rem;
        margin-bottom: 20px;
        font-weight: 300;
        position: relative;
      }
      
      .hero-text {
        font-size: 1.2rem;
        max-width: 700px;
        margin: 0 auto 30px;
        opacity: 0.9;
        position: relative;
      }
      
      /* Mission Section */
      .mission-section {
        background: #f8f9fa;
        padding: 80px 0;
      }
      
      .section-title {
        font-size: 2.5rem;
        font-weight: 800;
        margin-bottom: 15px;
        color: #0a3d62;
        position: relative;
      }
      
      .section-title:after {
        content: '';
        position: absolute;
        bottom: -10px;
        left: 50%;
        transform: translateX(-50%);
        width: 80px;
        height: 4px;
        background: linear-gradient(90deg, #1a936f, #88d498);
        border-radius: 2px;
      }
      
      .section-subtitle {
        font-size: 1.2rem;
        color: #5a7a8c;
        max-width: 600px;
        margin: 0 auto;
      }
      
      .mission-card {
        padding: 30px 25px;
        border-radius: 15px;
        text-align: center;
        height: 100%;
        background: white;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
        transition: all 0.3s ease;
      }
      
      .mission-card:hover {
        transform: translateY(-10px);
        box-shadow: 0 15px 40px rgba(0, 100, 200, 0.1);
      }
      
      .mission-icon {
        width: 80px;
        height: 80px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        margin: 0 auto 20px;
        font-size: 2rem;
        background: linear-gradient(135deg, #0a3d62, #64c8fa);
        color: white;
        box-shadow: 0 5px 15px rgba(10, 61, 98, 0.2);
      }
      
      .mission-card h3 {
        font-size: 1.5rem;
        color: #0a3d62;
        margin-bottom: 15px;
      }
      
      .mission-card p {
        color: #5a7a8c;
      }
      
      /* Tilapia Section */
      .tilapia-section {
        background: linear-gradient(to bottom, #e9f7fe, #d1edfc);
        padding: 80px 0;
      }
      
      .tilapia-image {
        height: 400px;
        background: url('https://images.unsplash.com/photo-1593111774240-d529f12e5c4f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1770&q=80');
        background-size: cover;
        background-position: center;
        border-radius: 15px;
        box-shadow: 0 15px 30px rgba(0, 50, 100, 0.1);
      }
      
      .tilapia-content {
        padding: 30px;
        background: white;
        border-radius: 15px;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
      }
      
      .tilapia-content h3 {
        font-size: 1.8rem;
        color: #0a3d62;
        margin-bottom: 20px;
      }
      
      .tilapia-content p {
        color: #5a7a8c;
        font-size: 1.1rem;
        margin-bottom: 25px;
      }
      
      .tilapia-features {
        margin-bottom: 30px;
      }
      
      .feature {
        display: flex;
        align-items: center;
        margin-bottom: 15px;
      }
      
      .feature i {
        color: #1a936f;
        font-size: 1.5rem;
        margin-right: 15px;
      }
      
      .feature span {
        font-size: 1.1rem;
        color: #0a3d62;
      }
      
      .tilapia-pricing {
        padding-top: 20px;
        border-top: 1px solid #eaeaea;
      }
      
      .price {
        font-size: 2.2rem;
        font-weight: 800;
        color: #1a936f;
        margin-bottom: 10px;
      }
      
      .note {
        font-size: 1rem;
        color: #5a7a8c;
        font-style: italic;
      }
      
      /* Impact Section */
      .impact-section {
        background: #f8f9fa;
        padding: 80px 0;
      }
      
      .impact-stat {
        padding: 30px 20px;
        background: white;
        border-radius: 15px;
        box-shadow: 0 10px 20px rgba(0, 0, 0, 0.05);
        transition: all 0.3s ease;
      }
      
      .impact-stat:hover {
        transform: translateY(-5px);
        box-shadow: 0 15px 30px rgba(0, 0, 0, 0.1);
      }
      
      .stat-value {
        font-size: 3rem;
        font-weight: 800;
        margin-bottom: 10px;
        background: linear-gradient(90deg, #0a3d62, #1a936f);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
      }
      
      .stat-label {
        font-size: 1.2rem;
        color: #5a7a8c;
      }
      
      /* Responsive styles */
      @media (max-width: 992px) {
        .hero-title {
          font-size: 2.8rem;
        }
        
        .section-title {
          font-size: 2rem;
        }
        
        .tilapia-image {
          height: 300px;
          margin-bottom: 30px;
        }
      }
      
      @media (max-width: 768px) {
        .hero-title {
          font-size: 2.3rem;
        }
        
        .hero-subtitle {
          font-size: 1.5rem;
        }
        
        .section-title {
          font-size: 1.8rem;
        }
        
        .stat-value {
          font-size: 2.5rem;
        }
      }
      
      @media (max-width: 576px) {
        .hero-title {
          font-size: 2rem;
        }
        
        .hero-subtitle {
          font-size: 1.3rem;
        }
        
        .section-title {
          font-size: 1.7rem;
        }
        
        .mission-card {
          margin-bottom: 20px;
        }
      }
    `}</style>
  </div>
);

export default Home;
